import 'package:chart_engine/chart_engine_apexcharts.dart';

void main() async {
  var series = ChartSeries(
      ['Jan','Feb','Mar'],
      {
        'A': [10,20,5],
        'B': [15,25,55],
        'C': [100,130,140]
      }
  );

  var charEngine = ChartEngineApexCharts();
  await charEngine.load();
  charEngine.renderLineChart(querySelector('#output'), series);
}
